const axios = require('axios');
await sendTrackedMessage(sock, remoteJid, '🧠 Fetching a fact...');
try {
  const res = await axios.get('https://uselessfacts.jsph.pl/api/v2/facts/random?language=en');
  if (res.data && res.data.text) {
    await sendTrackedMessage(sock, remoteJid, `🧠 ${res.data.text}`);
  } else {
    await sendTrackedMessage(sock, remoteJid, '❌ Could not fetch a fact.');
  }
} catch (e) {
  await sendTrackedMessage(sock, remoteJid, '❌ Fact service unavailable.');
}
